package com.hotroso.autopay.utils

import java.util.Locale

data class ParsedPayment(
    val shouldForward: Boolean,
    val isCredit: Boolean,
    val orderCode: String?,
    val amount: Long?,
    val bankName: String,
    val reason: String
)

/**
 * Parses incoming Android banking/wallet notifications on-device to:
 * 1. Extract the order code generated by the auto-payment web server (e.g. AP123456).
 * 2. Extract incoming credit amounts while rejecting outgoing debits.
 * 3. Filter out non-payment notifications so private messages are never forwarded.
 */
object PaymentNotificationParser {

    val KNOWN_BANK_PACKAGES: Map<String, String> = mapOf(
        "com.VCB" to "Vietcombank",
        "com.vcb.mobile" to "Vietcombank",
        "vn.com.techcombank.bb.app" to "Techcombank",
        "com.mbmobile" to "MBBank",
        "com.vnpay.vpbankonline" to "VPBank",
        "com.vnpay.bidv" to "BIDV",
        "mobile.acb.com.vn" to "ACB",
        "com.tpb.mb.gprsandroid" to "TPBank",
        "com.vietinbank.ipay" to "VietinBank",
        "com.sacombank.ewallet" to "Sacombank",
        "io.lifestyle.plus" to "Timo",
        "com.mservice.momotransfer" to "MoMo",
        "vn.com.vng.zalopay" to "ZaloPay"
    )

    private val SIGNED_AMOUNT_REGEX = Regex(
        """([+-])\s*(\d{1,3}(?:[.,]\d{3})+|\d{4,12})\s*(?:vnd|vnđ|đ|d\b)?""",
        RegexOption.IGNORE_CASE
    )

    private val DEBIT_KEYWORD_REGEX = Regex(
        """(?:bi\s+tru|bị\s+trừ|thanh\s+toan\s+thanh\s+cong|chi\s+tieu|rút\s+tiền|rut\s+tien|chuyen\s+di|chuyển\s+đi)""",
        RegexOption.IGNORE_CASE
    )

    private val CREDIT_KEYWORD_REGEX = Regex(
        """(?:nhận\s+được|nhan\s+duoc|ghi\s+có|ghi\s+co|biến\s+động|bien\s+dong|cộng|cong|số\s+tiền|so\s+tien|received|credited)\D{0,15}(\d{1,3}(?:[.,]\d{3})+|\d{4,12})\s*(?:vnd|vnđ|đ|d\b)?""",
        RegexOption.IGNORE_CASE
    )

    fun extractOrderCode(text: String, orderPrefix: String = "AP"): String? {
        val cleanPrefix = orderPrefix.replace(Regex("[^A-Za-z0-9]"), "").uppercase(Locale.ROOT)
            .ifEmpty { "AP" }
        val pattern = Regex("""\b($cleanPrefix[-_ ]?\d{6})\b""", RegexOption.IGNORE_CASE)
        val match = pattern.find(text) ?: return null
        return match.groupValues[1].replace(Regex("[-_ ]"), "").uppercase(Locale.ROOT)
    }

    fun parseVndNumber(raw: String): Long? {
        val digits = raw.replace(Regex("[.,_\\s]"), "")
        if (!digits.matches(Regex("^\\d+$"))) return null
        val value = digits.toLongOrNull() ?: return null
        return if (value > 0L) value else null
    }

    fun parse(
        packageName: String,
        title: String?,
        message: String?,
        orderPrefix: String = "AP",
        onlyKnownBankApps: Boolean = false
    ): ParsedPayment {
        val bankName = KNOWN_BANK_PACKAGES[packageName] ?: (title?.trim().takeUnless { it.isNullOrEmpty() } ?: packageName)

        if (onlyKnownBankApps && !KNOWN_BANK_PACKAGES.containsKey(packageName)) {
            return ParsedPayment(
                shouldForward = false,
                isCredit = false,
                orderCode = null,
                amount = null,
                bankName = bankName,
                reason = "Package $packageName is not in known bank apps"
            )
        }

        val combined = listOfNotNull(title?.trim(), message?.trim())
            .filter { it.isNotEmpty() }
            .joinToString(" | ")

        if (combined.isEmpty()) {
            return ParsedPayment(false, false, null, null, bankName, "Empty notification")
        }

        val orderCode = extractOrderCode(combined, orderPrefix)
            ?: return ParsedPayment(false, false, null, null, bankName, "No order code matching prefix $orderPrefix")

        val bodyToParse = message?.trim().takeUnless { it.isNullOrEmpty() } ?: combined

        val signedMatch = SIGNED_AMOUNT_REGEX.find(bodyToParse)
        if (signedMatch != null) {
            val sign = signedMatch.groupValues[1]
            val amount = parseVndNumber(signedMatch.groupValues[2])
            if (sign == "-") {
                return ParsedPayment(false, false, orderCode, amount, bankName, "Outgoing debit ignored")
            }
            if (amount != null) {
                return ParsedPayment(true, true, orderCode, amount, bankName, "Matched credit order $orderCode")
            }
        }

        if (DEBIT_KEYWORD_REGEX.containsMatchIn(bodyToParse)) {
            return ParsedPayment(false, false, orderCode, null, bankName, "Outgoing debit keyword detected")
        }

        val creditMatch = CREDIT_KEYWORD_REGEX.find(bodyToParse)
        if (creditMatch != null) {
            val amount = parseVndNumber(creditMatch.groupValues[1])
            if (amount != null) {
                return ParsedPayment(true, true, orderCode, amount, bankName, "Matched credit keyword for $orderCode")
            }
        }

        return ParsedPayment(false, false, orderCode, null, bankName, "No incoming credit amount found")
    }
}
